/**
 * Admin Seeder Script for EcoFone PostgreSQL Database
 * Complies with VULN-03 from System/EcoFone_Complete_Engineering_Compendium.md
 *
 * Usage:
 *   node prisma/seed-admin.js <initial_admin_password>
 *   (Default password if none provided: autogenerated 20-character secure alphanumeric string)
 */

const { PrismaClient } = require('@prisma/client');
const bcrypt = require('bcrypt');
const crypto = require('crypto');

const prisma = new PrismaClient();

async function main() {
  const customPassword = process.argv[2] || process.env.INITIAL_ADMIN_PASSWORD;
  const password = customPassword || crypto.randomBytes(12).toString('base64url');

  const saltRounds = 12;
  const hashedPassword = await bcrypt.hash(password, saltRounds);

  const admin = await prisma.subAdmin.upsert({
    where: { username: 'admin' },
    update: {
      password: hashedPassword,
      permissions: ['franchise', 'contact', 'stores', 'team', 'logs', 'security', 'reviews', 'certificates', 'inventory', 'cms', 'orders'],
    },
    create: {
      username: 'admin',
      password: hashedPassword,
      permissions: ['franchise', 'contact', 'stores', 'team', 'logs', 'security', 'reviews', 'certificates', 'inventory', 'cms', 'orders'],
    },
  });

  console.log('================================================================');
  console.log(' EcoFone Master Admin Initialized in PostgreSQL');
  console.log('================================================================');
  console.log(` Username : admin`);
  if (!customPassword) {
    console.log(` Generated Password : ${password}`);
    console.log(' [IMPORTANT] Please record this password securely now!');
  } else {
    console.log(' Password : [Provided via command line / environment]');
  }
  console.log(` SubAdmin ID        : ${admin.id}`);
  console.log('================================================================');
}

main()
  .catch((e) => {
    console.error('Failed to seed master admin:', e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
